<?php use FilamentManager\Core\View; ?>
<div class="toolbar"><h1><?= View::t('spools') ?></h1><?php if($app->auth()->user()['role']!=='viewer'): ?><a class="button" href="<?= View::e($basePath) ?>/spools/new">＋ <?= View::t('spools') ?></a><?php endif; ?></div><div class="table-wrap"><table><thead><tr><th><?= View::t('material') ?></th><th><?= View::t('manufacturer') ?></th><th><?= View::t('color') ?></th><th><?= View::t('remaining') ?></th><th><?= View::t('storage_location') ?></th><th>NFC</th><th><?= View::t('status') ?></th><th></th></tr></thead><tbody><?php foreach($spools as $s): $hex=preg_match('/^#[0-9A-Fa-f]{6}$/',(string)$s['color_hex'])?$s['color_hex']:'#d0d5dd'; ?><tr><td><strong><?= View::e($s['material_type']) ?></strong><br><small><?= View::e($s['commercial_name']) ?></small></td><td><?= View::e($s['manufacturer_name']) ?></td><td><input class="color-swatch" type="color" value="<?= View::e($hex) ?>" disabled> <?= View::e($s['color_name']) ?></td><td><?= View::e(number_format((float)$s['current_net_weight_g'],0,',',' ')) ?> g</td><td><?= View::e($s['location_name']?:View::t('without_location')) ?></td><td><?= View::e($s['tag_uid']?:'—') ?></td><td><?= View::t('spool_status_'.$s['status']) ?></td><td><a class="button secondary-button action-button" href="<?= View::e($basePath) ?>/spools/<?= View::e($s['id']) ?>/edit"><?= View::t('edit') ?></a></td></tr><?php endforeach; ?></tbody></table></div>
